import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_perfect_cube(n):
    if n < 0:
        return False
    if n == 0:
        return True
    # Calculate the integer cube root
    root = round(n**(1/3))
    return root**3 == n, root

primes_q = [2, 3, 5, 7, 11, 13, 17, 19]
results = []

for q in primes_q:
    N = q**2 - q + 1
    is_cube, p = is_perfect_cube(N)

    result_entry = {
        "q": q,
        "N": N,
        "is_cube": is_cube,
        "p": p,
        "p_is_prime": False,
        "p_not_equal_to_q": False
    }

    if is_cube:
        result_entry["p_is_prime"] = is_prime(p)
        result_entry["p_not_equal_to_q"] = p != q

    results.append(result_entry)

# Print results in a readable format for note writing
print("--- Test Results ---")
for res in results:
    print(f"q = {res['q']}: N = {res['N']}")
    if res['is_cube']:
        print(f"  -> p = {res['p']} (integer cube root)")
        print(f"  -> p is prime: {res['p_is_prime']}")
        print(f"  -> p != q: {res['p_not_equal_to_q']}")
    else:
        print(f"  -> N is not a perfect cube.")

